        ["(empty)"] = "(пусто)",
        ["Self-test: the game's crossbar is not what Gripbar expects (%s). Own X / Y / B / A may not hold the face buttons; please report it with /grip debug."] = "Самопроверка: крестовина игры не такая, как ожидает Gripbar (%s). Свои X / Y / B / A могут не удерживать кнопки; сообщите об этом, приложив журнал /grip debug.",

        -- GameActions.lua: the picker (macro names stay English)
        ["Bags button"] = "Кнопка сумок",
        ["Quests button"] = "Кнопка заданий",
        ["Buffs button"] = "Кнопка эффектов",
        ["Last foe"] = "Прошлый противник",
        ["Game button %d"] = "Игровая кнопка %d",
        ["A shortcut button of the game's LB / RB bars (%s)."] = "Быстрая кнопка игровых панелей LB / RB (%s).",
        ["The game's smart interact (X): loot, talk, gather, attack the soft target."] = "Умное взаимодействие игры (X): добыча, разговор, сбор ресурсов, атака мягкой цели.",
        ["The game's inspect / target button (Y)."] = "Игровая кнопка осмотра / выбора цели (Y).",
        ["The game's back / cancel button (B)."] = "Игровая кнопка «Назад» / отмены (B).",
        ["The game's jump (A). Held on a Gripbar slot it keeps rising in water."] = "Игровой прыжок (A). Если удерживать его в слоте Gripbar, продолжается подъём в воде.",
        ["Target enemy"] = "Цель: враг",
