        ["Follow"] = "Следовать",
        ["Follows your target."] = "Следует за вашей целью.",
        ["Start attack"] = "Начать атаку",
        ["Starts the melee auto attack on your target."] = "Начинает автоатаку ближнего боя по цели.",
        ["Stop attack"] = "Прервать атаку",
        ["Stops the auto attack."] = "Прерывает автоатаку.",
        ["Sit / stand"] = "Сесть / встать",
        ["Sits down (stands up from any move)."] = "Садится (встаёт при любом движении).",
