        ["Usage: /grip spread [top|bottom] <x> <y>  (0-200, default top 26 32, bottom 26 32), or /grip spread reset"] = "Использование: /grip spread [top|bottom] <x> <y>  (0-200, по умолчанию top 26 32, bottom 26 32) или /grip spread reset",
